from collections import deque


def minTeamGap(n, dislikes):
    adj = [[] for _ in range(n)]
    for a, b in dislikes:
        adj[a].append(b)
        adj[b].append(a)
    color = [-1] * n
    reach = 1
    for s in range(n):
        if color[s] != -1:
            continue
        color[s] = 0
        count = [1, 0]
        queue = deque([s])
        while queue:
            u = queue.popleft()
            for v in adj[u]:
                if color[v] == -1:
                    color[v] = 1 - color[u]
                    count[color[v]] += 1
                    queue.append(v)
                elif color[v] == color[u]:
                    return -1
        reach = (reach << count[0]) | (reach << count[1])
    best = n
    for size in range(n + 1):
        if (reach >> size) & 1:
            best = min(best, abs(n - 2 * size))
    return best
